sanitize = (obj) => {
  if (!obj || typeof obj !== 'object') return obj;
  const cleaned = Array.isArray(obj) ? [] : {};
  for (const [key, value] of Object.entries(obj)) {
    if (value === undefined || value === null) continue;
    cleaned[key] = typeof value === 'object' ? sanitize(value) : value;
  }
  return cleaned;
}

